UPDATE product_content c SET whats_included = '["Free transport between venues", "2–4 complimentary shots", "Exclusive drink deals", "VIP entry at all stops", "Dedicated host all night"]'::jsonb, whats_not_included = '["Extra drinks", "Cover charge on DJ nights only — entry is free on all regular nights", "Ride home", "1 drink minimum at free-entry venues"]'::jsonb, important_info = '["The exact meet-up spot for the first venue is shared in our WhatsApp group chat by 7 PM on the event day.", "Be at the first bar by 9:30 PM sharp — if you do not make it to the first bar, you will be marked as a no-show.", "The event is confirmed once we reach a minimum of 5 participants; a WhatsApp group is created and the meet-up location shared by 7 PM on the day.", "If the minimum is not reached, you will receive an email with options to reschedule or receive a full refund.", "Dress code — Men: no shorts, tank tops, sportswear, sandals, or flip-flops.", "Dress code — Women: no sandals or flip-flops (ankle-strap sandals are fine).", "ID: physical passport required for under 25; digital ID may work if 25+.", "Eat before you go — grab a meal before the crawl for energy.", "Bring cash: ฿2,000–3,000 for drinks, cover charges, and tips.", "Charge your phone — WhatsApp is your lifeline for the night.", "Your host is there to help — ask anything during the night."]'::jsonb, itinerary = '[{"title": "9:30 – 10:30 PM", "description": "Meet & greet at the first bar with a welcome shot to kick off the night."}, {"title": "10:45 – 11:45 PM", "description": "Move to the second venue — unique décor and great atmosphere."}, {"title": "12:00 – 1:00 AM", "description": "Hit an upbeat venue to dance and soak in the Bangkok nightlife energy."}, {"title": "1:30 – 2:30 AM", "description": "Wrap up at a high-energy spot to end the night on a memorable note."}]'::jsonb, updated_at = now() FROM products p WHERE p.id = c.product_id AND p.slug = 'bangkok-club-crawl';
